DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT114-S2-Q21$pilot$ AND c.letter=$pilot$B$pilot$ AND c.choice_text=$pilot$People who are not athletes require neither stronger connective tissue nor muscle strength.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT114-S2-Q21 B'; END IF; END $guard$;
